// Loops, vectors and strings
#include <algorithm>
#include <iostream>
#include <numeric>
#include <string>
#include <vector>

int main() {
    std::vector<int> scores = {7, 3, 9, 4, 10, 6};

    for (int i = 0; i < 3; i++) {
        std::cout << "count " << i << "\n";
    }

    int total = std::accumulate(scores.begin(), scores.end(), 0);
    std::cout << "total = " << total << "\n";

    std::sort(scores.begin(), scores.end());
    std::cout << "sorted:";
    for (int s : scores) std::cout << " " << s;
    std::cout << "\n";

    std::string word = "English++";
    std::string backwards(word.rbegin(), word.rend());
    std::cout << word << " backwards is " << backwards << "\n";
    std::cout << word << " has " << word.size() << " letters\n";

    int n = 10;
    while (n > 1) {
        n = (n % 2 == 0) ? n / 2 : 3 * n + 1;
        std::cout << n << (n > 1 ? " -> " : "\n");
    }
    return 0;
}

