// A class with a field, a constructor and methods
#include <iostream>
#include <string>
#include <vector>

class Dog {
public:
    Dog(std::string name, int age) : name_(name), age_(age) {}
    void bark() const { std::cout << name_ << " says woof!\n"; }
    void birthday() { age_++; }
    int age() const { return age_; }
    const std::string& name() const { return name_; }

private:
    std::string name_;
    int age_;
};

int main() {
    std::vector<Dog> dogs = {Dog("Rex", 3), Dog("Bella", 5)};
    for (auto& d : dogs) {
        d.bark();
        d.birthday();
        std::cout << d.name() << " is now " << d.age() << "\n";
    }
    return 0;
}

