// raylib from C++: a bouncing ball (Space reverses it, touch or click moves it)
#include "raylib.h"
#include <string>

int main() {
    InitWindow(800, 450, "Bouncing Ball");
    SetTargetFPS(60);

    Vector2 pos = {400, 225};
    Vector2 speed = {5, 4};
    float radius = 30;
    int bounces = 0;

    while (!WindowShouldClose()) {
        pos.x += speed.x;
        pos.y += speed.y;
        if (pos.x < radius || pos.x > GetScreenWidth() - radius) { speed.x = -speed.x; bounces++; }
        if (pos.y < radius || pos.y > GetScreenHeight() - radius) { speed.y = -speed.y; bounces++; }
        if (IsKeyPressed(KEY_SPACE)) { speed.x = -speed.x; speed.y = -speed.y; }
        if (IsMouseButtonDown(MOUSE_BUTTON_LEFT)) pos = GetMousePosition();

        BeginDrawing();
        ClearBackground(RAYWHITE);
        DrawCircleV(pos, radius, MAROON);
        DrawText(("Bounces: " + std::to_string(bounces)).c_str(), 10, 10, 24, DARKGRAY);
        DrawFPS(GetScreenWidth() - 100, 10);
        EndDrawing();
    }
    CloseWindow();
    return 0;
}

