// raylib from C++: a 3D orbit camera around a little city of cubes
#include "raylib.h"
#include <cmath>

int main() {
    InitWindow(800, 450, "Orbit Camera");
    SetTargetFPS(60);

    Camera3D camera = {};
    camera.position = {12.0f, 8.0f, 12.0f};
    camera.target = {0.0f, 1.0f, 0.0f};
    camera.up = {0.0f, 1.0f, 0.0f};
    camera.fovy = 45.0f;
    camera.projection = CAMERA_PERSPECTIVE;

    float angle = 0.0f;
    while (!WindowShouldClose()) {
        if (IsKeyDown(KEY_LEFT)) angle -= 0.03f;
        else if (IsKeyDown(KEY_RIGHT)) angle += 0.03f;
        else angle += 0.01f;
        camera.position.x = 17.0f * std::cos(angle);
        camera.position.z = 17.0f * std::sin(angle);

        BeginDrawing();
        ClearBackground(SKYBLUE);
        BeginMode3D(camera);
        DrawPlane({0, 0, 0}, {20, 20}, DARKGREEN);
        for (int x = -2; x <= 2; x++) {
            for (int z = -2; z <= 2; z++) {
                float h = 1.0f + (float)((x * 7 + z * 13 + 20) % 5);
                Color c = ColorFromHSV((float)((x + 2) * 40 + (z + 2) * 15), 0.6f, 0.9f);
                DrawCube({x * 3.0f, h / 2, z * 3.0f}, 1.6f, h, 1.6f, c);
                DrawCubeWires({x * 3.0f, h / 2, z * 3.0f}, 1.6f, h, 1.6f, DARKGRAY);
            }
        }
        DrawGrid(20, 1.0f);
        EndMode3D();
        DrawText("Left / Right to orbit", 10, 10, 22, DARKBLUE);
        DrawFPS(GetScreenWidth() - 100, 10);
        EndDrawing();
    }
    CloseWindow();
    return 0;
}

