// raylib from C++: Star Catcher — move the paddle with Left/Right (or A/D), catch the stars, miss three and it's over
#include "raylib.h"
#include <string>
#include <vector>

struct Star {
    Vector2 pos;
    float speed;
};

int main() {
    InitWindow(800, 450, "Star Catcher");
    SetTargetFPS(60);

    Rectangle paddle = {350, 410, 110, 18};
    std::vector<Star> stars;
    int score = 0, missed = 0, frame = 0;
    bool over = false;

    while (!WindowShouldClose()) {
        if (!over) {
            if (IsKeyDown(KEY_LEFT) || IsKeyDown(KEY_A)) paddle.x -= 8;
            if (IsKeyDown(KEY_RIGHT) || IsKeyDown(KEY_D)) paddle.x += 8;
            if (IsMouseButtonDown(MOUSE_BUTTON_LEFT)) paddle.x = GetMouseX() - paddle.width / 2;
            if (paddle.x < 0) paddle.x = 0;
            if (paddle.x > 800 - paddle.width) paddle.x = 800 - paddle.width;

            if (frame++ % 40 == 0) stars.push_back({{(float)GetRandomValue(20, 780), -10}, (float)GetRandomValue(3, 6)});
            for (auto& s : stars) s.pos.y += s.speed;
            for (size_t i = 0; i < stars.size();) {
                if (CheckCollisionCircleRec(stars[i].pos, 10, paddle)) { score++; stars.erase(stars.begin() + i); }
                else if (stars[i].pos.y > 460) { missed++; stars.erase(stars.begin() + i); }
                else i++;
            }
            if (missed >= 3) over = true;
        } else if (IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_R)) {
            stars.clear(); score = 0; missed = 0; over = false;
        }

        BeginDrawing();
        ClearBackground({12, 20, 48, 255});
        for (auto& s : stars) DrawPoly(s.pos, 5, 12, frame * 3.0f, GOLD);
        DrawRectangleRounded(paddle, 0.5f, 6, SKYBLUE);
        DrawText(("Score " + std::to_string(score)).c_str(), 10, 10, 28, RAYWHITE);
        DrawText(("Missed " + std::to_string(missed) + "/3").c_str(), 640, 10, 24, ORANGE);
        if (over) {
            DrawText("GAME OVER", 250, 170, 60, RED);
            DrawText("Press Enter or R to play again", 230, 245, 24, RAYWHITE);
        }
        EndDrawing();
    }
    CloseWindow();
    return 0;
}

